            ))}
          </tbody>
        </table>
      )}

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        <CallsignInput
          ref={callsignRef}
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v }))}
          onSelect={op => setForm(f => ({ ...f, operator: op, callsign: op.callsign }))}
          className="w-24 sm:w-28"
        />
        <input
          type="text"
          value={form.operator?.name || ''}
          disabled
          placeholder="Name"
          className="border border-gray-200 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 bg-gray-50 text-gray-500 truncate hidden sm:block"
        />
        <input
          type="text"
          value={form.operator?.qth || ''}
          disabled
          placeholder="QTH"
          className="border border-gray-200 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 bg-gray-50 text-gray-500 truncate hidden sm:block"
        />
        <input
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
