   195→  const handleDelete = async (reportId: number) => {
   196→    if (!confirm('Rapport löschen?')) return;
   197→    try {
   198→      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
   199→      onReportDeleted(reportId);
   200→    } catch {}
   201→  };
   202→
   203→  return (
   204→    <div className="space-y-2">
   205→      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
   206→        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
   207→        const defaultRepId = blRepSelection[bl.code] || 0;
   208→        // Match reports by repeater's Bundesland (where the report was entered)
   209→        const blReports = reports.filter(r => r.repeater_bundesland_code === bl.code);
   210→        const isCollapsed = collapsedBl.has(bl.code);
   211→        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;
   212→
   213→        return (
   214→          <div key={bl.code} className="bg-white rounded-lg shadow-sm">
   215→            <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
   216→              <div
   217→                onClick={() => toggleBl(bl.code)}
   218→                className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
   219→              >
   220→                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
   221→                <span className="font-medium text-xs sm:text-sm truncate">{bl.name}</span>
   222→                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
   223→              </div>
   224→              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
   225→                <button
   226→                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
   227→                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
   228→                >
   229→                  + Umsetzer
   230→                </button>
   231→                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
   232→                <input
   233→                  type="text"
   234→                  value={blOpCallsigns[bl.code] || ''}
   235→                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
   236→                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
   237→                  placeholder="Rufz."
   238→                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
   239→                />
   240→              </div>
   241→            </div>
   242→
   243→            {!isCollapsed && (
   244→              <div>
   245→                {addRepBl === bl.code && (
   246→                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
   247→                    <input
   248→                      type="text"
   249→                      value={newRepName}
   250→                      onChange={e => setNewRepName(e.target.value)}
   251→                      placeholder="Name"
   252→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
   253→                      autoFocus
   254→                    />
   255→                    <input
   256→                      type="text"
   257→                      value={newRepFreq}
   258→                      onChange={e => setNewRepFreq(e.target.value)}
   259→                      placeholder="MHz"
   260→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   261→                    />
   262→                    <input
   263→                      type="text"
   264→                      value={newRepCallsign}
   265→                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
   266→                      placeholder="Rufz."
   267→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   268→                    />
   269→                    <button
   270→                      onClick={() => addRepeater(bl.code)}
   271→                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
   272→                    >
   273→                      OK
   274→                    </button>
   275→                    <button
   276→                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
   277→                      className="text-gray-400 hover:text-gray-600 text-xs"
   278→                    >
   279→                      Abbrechen
   280→                    </button>
   281→                  </div>
   282→                )}
   283→                <div className="divide-y divide-gray-100">
   284→                  {blBezirke.map(bz => {
   285→                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
   286→                    return (
   287→                      <BezirkRow
   288→                        key={bz.code}
   289→                        bezirk={bz}
   290→                        reports={bzReports}
   291→                        linkedRepeaters={linkedRepeaters}
   292→                        defaultRepeaterId={defaultRepId}
   293→                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
   294→                        onEdit={handleEdit}
   295→                        onDelete={handleDelete}
   296→                        editingId={editingId}
   297→                        editForm={editForm}
   298→                        onEditChange={setEditForm}
   299→                        onEditSave={handleUpdate}
   300→                        onEditCancel={() => setEditingId(null)}
   301→                      />
   302→                    );
   303→                  })}
   304→                  {/* Reports without matching bezirk — shown directly as list items */}
   305→                  {(() => {
   306→                    const bzCodes = new Set(blBezirke.map(b => b.code));
   307→                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
   308→                    if (unassigned.length === 0) return null;
   309→                    return (
   310→                      <div className="px-3 py-1.5">
   311→                        <table className="w-full text-xs mb-1">
   312→                          <tbody>
   313→                            {unassigned.map((r, idx) => (
   314→                              <tr key={r.id} className="hover:bg-blue-50 group">
   315→                                {editingId === r.id ? (
   316→                                  <td colSpan={5} className="py-0.5">
   317→                                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1">
   318→                                      <span className="font-mono font-medium">{r.callsign}</span>
   319→                                      <input value={editForm.rapport} onChange={e => setEditForm({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-20" autoFocus />
   320→                                      <input value={editForm.notes} onChange={e => setEditForm({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-20" />
   321→                                      <button onClick={handleUpdate} className="text-green-600 text-xs font-bold">OK</button>
   322→                                      <button onClick={() => setEditingId(null)} className="text-gray-400 text-xs">X</button>
   323→                                    </div>
   324→                                  </td>
   325→                                ) : (
   326→                                  <>
   327→                                    <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   328→                                    <td className="py-0.5 cursor-pointer" onClick={() => handleEdit(r)}>
   329→                                      <span className="font-mono font-medium">{r.callsign}</span>
   330→                                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
   331→                                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
   332→                                    </td>
   333→                                    <td className="py-0.5 font-mono text-gray-500 w-24 cursor-pointer" onClick={() => handleEdit(r)}>
   334→                                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   335→                                    </td>
   336→                                    <td className="py-0.5 text-gray-500 cursor-pointer" onClick={() => handleEdit(r)}>{r.notes || ''}</td>
   337→                                    <td className="py-0.5 w-4">
   338→                                      <button onClick={() => handleDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   339→                                    </td>
   340→                                  </>
   341→                                )}
   342→                              </tr>
   343→                            ))}
   344→                          </tbody>
   345→                        </table>
   346→                      </div>
   347→                    );
   348→                  })()}
   349→                </div>
   350→              </div>
   351→            )}
   352→          </div>
   353→        );
   354→      })}
   355→    </div>
   356→  );
   357→}
