            >
              Q{q}
            </button>
          ))}
          <button
            onClick={applyYear}
            className="bg-gray-100 hover:bg-blue-100 text-gray-700 hover:text-[#1e3a5f] px-3 py-1.5 rounded text-sm font-medium"
