    90→          site_name: name,
    91→          frequency_mhz: freq,
    92→          callsign: newRepCallsign || null,
    93→          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
    94→          type: 'repeater',
    95→          bundesland_code: blCode,
    96→        }),
    97→      });
    98→      setLinkedRepeaters(prev => [...prev, rep]);
    99→      setNewRepName('');
   100→      setNewRepFreq('');
   101→      setNewRepCallsign('');
   102→      setAddRepBl(null);
   103→    } catch {}
   104→  };
   105→
   106→  const toggleBl = (code: string) => {
   107→    setCollapsedBl(prev => {
   108→      const next = new Set(prev);
   109→      if (next.has(code)) next.delete(code); else next.add(code);
   110→      return next;
   111→    });
   112→  };
   113→
   114→  const parseRapport = (raw: string) => {
   115→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
   116→    if (!match) return { readability: null, strength: null, db_over_s9: null };
   117→    return {
   118→      readability: parseInt(match[1]),
   119→      strength: parseInt(match[2]),
   120→      db_over_s9: match[3]?.trim() || null,
   121→    };
   122→  };
   123→
   124→  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
   125→    try {
   126→      if (!repeaterId) return;
   127→      const operator = await getOrCreateOperator(form.callsign, form.operator);
   128→      if (!operator) return;
   129→
   130→      // Set operator's bezirk_code to match the row they were entered in
   131→      if (bezirkCode && bezirkCode !== '??') {
   132→        apiFetch(`/api/v1/operators/${operator.id}`, {
   133→          method: 'PATCH',
   134→          body: JSON.stringify({ bezirk_code: bezirkCode }),
   135→        }).catch(() => {});
   136→      }
   137→
   138→      const parsed = parseRapport(form.rapport);
   139→
   140→      try {
   141→        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
   142→          method: 'POST',
   143→          body: JSON.stringify({
   144→            operator_id: operator.id,
   145→            repeater_id: repeaterId,
   146→            ...parsed,
   147→            notes: form.notes || null,
   148→          }),
   149→        });
   150→        // Force bezirk_code on report so it shows in the correct row immediately
   151→        if (bezirkCode && bezirkCode !== '??') report.bezirk_code = bezirkCode;
   152→        onReportCreated(report);
   153→      } catch (err: any) {
   154→        if (err.message?.includes('existiert')) {
   155→          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === repeaterId);
   156→          if (existing) {
   157→            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
   158→              method: 'PATCH',
   159→              body: JSON.stringify({ ...parsed, notes: form.notes || null }),
   160→            });
   161→            if (bezirkCode && bezirkCode !== '??') updated.bezirk_code = bezirkCode;
   162→            onReportUpdated(updated);
   163→          }
   164→        }
   165→      }
   166→    } catch {
   167→    }
   168→  };
   169→
   170→  const handleEdit = (report: any) => {
   171→    setEditingId(report.id);
   172→    setEditForm({
   173→      callsign: report.callsign,
   174→      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
   175→      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
   176→      notes: report.notes || '',
   177→      opName: report.operator_name || '',
   178→      opQth: report.operator_qth || '',
   179→    });
   180→  };
   181→
   182→  const handleUpdate = async () => {
   183→    if (!editingId) return;
   184→    const parsed = parseRapport(editForm.rapport);
   185→    try {
   186→      // Save operator name/qth if changed
   187→      if (editForm.operator?.id) {
   188→        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
   189→        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
   190→        if (nameChanged || qthChanged) {
   191→          const patch: any = {};
   192→          if (nameChanged) patch.name = editForm.opName || null;
   193→          if (qthChanged) patch.qth = editForm.opQth || null;
   194→          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
   195→            method: 'PATCH',
   196→            body: JSON.stringify(patch),
   197→          });
   198→        }
   199→      }
   200→      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
   201→        method: 'PATCH',
   202→        body: JSON.stringify({ ...parsed, notes: editForm.notes || null }),
   203→      });
   204→      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
   205→      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
   206→      onReportUpdated(updated);
   207→      setEditingId(null);
   208→    } catch {}
   209→  };
   210→
   211→  const handleDelete = async (reportId: number) => {
   212→    if (!confirm('Rapport löschen?')) return;
   213→    try {
   214→      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
   215→      onReportDeleted(reportId);
   216→    } catch {}
   217→  };
   218→
   219→  return (
   220→    <div className="space-y-2">
   221→      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
   222→        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
   223→        const defaultRepId = blRepSelection[bl.code] || 0;
   224→        // Match reports by repeater's Bundesland (where the report was entered)
   225→        const blReports = reports.filter(r => r.repeater_bundesland_code === bl.code);
   226→        const isCollapsed = collapsedBl.has(bl.code);
   227→        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;
   228→
   229→        return (
   230→          <div key={bl.code} className="bg-white rounded-lg shadow-sm">
   231→            <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
   232→              <div
   233→                onClick={() => toggleBl(bl.code)}
   234→                className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
   235→              >
   236→                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
   237→                <span className="font-medium text-xs sm:text-sm truncate">{bl.name}</span>
   238→                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
   239→              </div>
   240→              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
   241→                <button
   242→                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
   243→                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
   244→                >
   245→                  + Umsetzer
   246→                </button>
   247→                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
   248→                <input
   249→                  type="text"
   250→                  value={blOpCallsigns[bl.code] || ''}
   251→                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
   252→                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
   253→                  placeholder="Rufz."
   254→                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
   255→                />
   256→              </div>
   257→            </div>
   258→
   259→            {!isCollapsed && (
   260→              <div>
   261→                {addRepBl === bl.code && (
   262→                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
   263→                    <input
   264→                      type="text"
   265→                      value={newRepName}
   266→                      onChange={e => setNewRepName(e.target.value)}
   267→                      placeholder="Name"
   268→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
   269→                      autoFocus
   270→                    />
   271→                    <input
   272→                      type="text"
   273→                      value={newRepFreq}
   274→                      onChange={e => setNewRepFreq(e.target.value)}
   275→                      placeholder="MHz"
   276→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   277→                    />
   278→                    <input
   279→                      type="text"
   280→                      value={newRepCallsign}
   281→                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
   282→                      placeholder="Rufz."
   283→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   284→                    />
   285→                    <button
   286→                      onClick={() => addRepeater(bl.code)}
   287→                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
   288→                    >
   289→                      OK
   290→                    </button>
   291→                    <button
   292→                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
   293→                      className="text-gray-400 hover:text-gray-600 text-xs"
   294→                    >
   295→                      Abbrechen
   296→                    </button>
   297→                  </div>
   298→                )}
   299→                <div className="divide-y divide-gray-100">
   300→                  {blBezirke.map(bz => {
   301→                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
   302→                    return (
   303→                      <BezirkRow
   304→                        key={bz.code}
   305→                        bezirk={bz}
   306→                        reports={bzReports}
   307→                        linkedRepeaters={linkedRepeaters}
   308→                        defaultRepeaterId={defaultRepId}
   309→                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
   310→                        onEdit={handleEdit}
   311→                        onDelete={handleDelete}
   312→                        editingId={editingId}
   313→                        editForm={editForm}
   314→                        onEditChange={setEditForm}
   315→                        onEditSave={handleUpdate}
   316→                        onEditCancel={() => setEditingId(null)}
   317→                      />
   318→                    );
   319→                  })}
   320→                  {/* Reports without matching bezirk — shown directly as list items */}
   321→                  {(() => {
   322→                    const bzCodes = new Set(blBezirke.map(b => b.code));
   323→                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
   324→                    if (unassigned.length === 0) return null;
   325→                    return (
   326→                      <div className="px-3 py-1.5">
   327→                        <table className="w-full text-xs mb-1">
   328→                          <tbody>
   329→                            {unassigned.map((r, idx) => (
   330→                              <tr key={r.id} className="hover:bg-blue-50 group">
   331→                                {editingId === r.id ? (
   332→                                  <td colSpan={5} className="py-0.5">
   333→                                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); handleUpdate(); } }}>
   334→                                      <span className="font-mono font-medium">{r.callsign}</span>
   335→                                      <input value={editForm.opName} onChange={e => setEditForm({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-20 hidden sm:block" />
   336→                                      <input value={editForm.opQth} onChange={e => setEditForm({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-16 hidden sm:block" />
   337→                                      <input value={editForm.rapport} onChange={e => setEditForm({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-20" autoFocus />
   338→                                      <input value={editForm.notes} onChange={e => setEditForm({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-20" />
   339→                                      <button onClick={handleUpdate} className="text-green-600 text-xs font-bold">OK</button>
   340→                                      <button onClick={() => setEditingId(null)} className="text-gray-400 text-xs">X</button>
   341→                                    </div>
   342→                                  </td>
   343→                                ) : (
   344→                                  <>
   345→                                    <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   346→                                    <td className="py-0.5 cursor-pointer" onClick={() => handleEdit(r)}>
   347→                                      <span className="font-mono font-medium">{r.callsign}</span>
   348→                                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
   349→                                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
   350→                                    </td>
   351→                                    <td className="py-0.5 font-mono text-gray-500 w-24 cursor-pointer" onClick={() => handleEdit(r)}>
   352→                                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   353→                                    </td>
   354→                                    <td className="py-0.5 text-gray-500 cursor-pointer" onClick={() => handleEdit(r)}>{r.notes || ''}</td>
   355→                                    <td className="py-0.5 w-4">
   356→                                      <button onClick={() => handleDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   357→                                    </td>
   358→                                  </>
   359→                                )}
   360→                              </tr>
   361→                            ))}
   362→                          </tbody>
   363→                        </table>
   364→                      </div>
   365→                    );
   366→                  })()}
   367→                </div>
   368→              </div>
   369→            )}
   370→          </div>
   371→        );
   372→      })}
   373→    </div>
   374→  );
   375→}
   376→
   377→interface BezirkRowProps {
   378→  bezirk: any;
   379→  reports: any[];
   380→  linkedRepeaters: any[];
   381→  defaultRepeaterId: number;
   382→  onSubmit: (repeaterId: number, form: EntryForm) => void;
   383→  onEdit: (report: any) => void;
   384→  onDelete: (id: number) => void;
   385→  editingId: number | null;
   386→  editForm: EntryForm;
   387→  onEditChange: (form: EntryForm) => void;
   388→  onEditSave: () => void;
   389→  onEditCancel: () => void;
   390→}
   391→
   392→function BezirkRow({ bezirk, reports, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, editingId, editForm, onEditChange, onEditSave, onEditCancel }: BezirkRowProps) {
   393→  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '' });
   394→  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
   395→  const callsignRef = useRef<CallsignInputRef>(null);
   396→
   397→  useEffect(() => {
   398→    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
   399→  }, [defaultRepeaterId]);
   400→
   401→  const handleSubmit = (e: FormEvent) => {
   402→    e.preventDefault();
   403→    if (!form.callsign && !form.operator) return;
   404→    if (!repeaterId) return;
   405→    onSubmit(repeaterId, form);
   406→    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '' });
   407→    setTimeout(() => callsignRef.current?.focus(), 50);
   408→  };
   409→
   410→  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
   411→    if (!form.operator?.id) return;
   412→    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
   413→    if (value === original) return;
   414→    apiFetch(`/api/v1/operators/${form.operator.id}`, {
   415→      method: 'PATCH',
   416→      body: JSON.stringify({ [field]: value || null }),
   417→    }).then(() => {
   418→      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
   419→    }).catch(() => {});
   420→  };
   421→
   422→  return (
   423→    <div className="px-2 sm:px-3 py-1.5">
   424→      {bezirk.code !== '??' && (
   425→        <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
   426→          <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
   427→            {bezirk.code}
   428→          </span>
   429→          <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
   430→          {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
   431→        </div>
   432→      )}
   433→
   434→      {reports.length > 0 && (
   435→        <table className="w-full text-xs mb-1">
   436→          <tbody>
   437→            {reports.map((r, idx) => (
   438→              <tr key={r.id} className="hover:bg-blue-50 group">
   439→                {editingId === r.id ? (
   440→                  <td colSpan={5} className="py-0.5">
   441→                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
   442→                      <span className="font-mono font-medium">{r.callsign}</span>
   443→                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
   444→                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
   445→                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
   446→                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
   447→                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
   448→                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
   449→                    </div>
   450→                  </td>
   451→                ) : (
   452→                  <>
   453→                    <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   454→                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
   455→                      <span className="font-mono font-medium">{r.callsign}</span>
   456→                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
   457→                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
   458→                    </td>
   459→                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
   460→                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   461→                    </td>
   462→                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
   463→                    <td className="py-0.5 w-4">
   464→                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   465→                    </td>
   466→                  </>
   467→                )}
   468→              </tr>
   469→            ))}
   470→          </tbody>
   471→        </table>
   472→      )}
   473→
   474→      <form onSubmit={handleSubmit} className="flex items-center gap-1">
   475→        {linkedRepeaters.length > 0 && (
   476→          <select
   477→            value={repeaterId || ''}
   478→            onChange={e => setRepeaterId(parseInt(e.target.value))}
   479→            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
   480→          >
   481→            {linkedRepeaters.map(r => (
   482→              <option key={r.id} value={r.id}>
   483→                {r.site_name || r.short_name}
   484→              </option>
   485→            ))}
   486→          </select>
   487→        )}
   488→        <CallsignInput
   489→          ref={callsignRef}
   490→          value={form.callsign}
   491→          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
   492→          onSelect={op => setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }))}
   493→          className="w-24 sm:w-28"
   494→        />
   495→        <input
   496→          type="text"
   497→          value={form.opName}
   498→          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
   499→          onBlur={e => saveOperatorField('name', e.target.value)}
   500→          placeholder="Name"
   501→          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
   502→        />
   503→        <input
   504→          type="text"
   505→          value={form.opQth}
   506→          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
   507→          onBlur={e => saveOperatorField('qth', e.target.value)}
   508→          placeholder="QTH"
   509→          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
   510→        />
   511→        <input
   512→          type="text"
   513→          value={form.rapport}
