   100→// ADIF export across a date range
   101→reportsRouter.get('/adif', (req, res) => {
   102→  const { from, to } = req.query;
   103→  if (!from || !to) {
   104→    res.status(400).json({ error: 'from und to Parameter erforderlich (YYYY-MM-DD)' });
   105→    return;
   106→  }
   107→
   108→  const db = getDb();
   109→
   110→  const exercises = db.prepare(
   111→    `SELECT id, date FROM exercises WHERE date >= ? AND date <= ? ORDER BY date ASC`
   112→  ).all(from, to) as { id: string; date: string }[];
   113→
   114→  if (exercises.length === 0) {
   115→    res.status(404).json({ error: 'Keine Übungen im gewählten Zeitraum' });
   116→    return;
   117→  }
   118→
   119→  const ids = exercises.map(e => e.id);
   120→  const placeholders = ids.map(() => '?').join(',');
   121→
   122→  const reports = db.prepare(
   123→    `SELECT sr.readability, sr.strength, sr.db_over_s9, sr.notes, sr.created_at,
   124→      o.callsign, o.name as op_name, o.qth,
   125→      r.short_name, r.frequency_mhz, r.band, r.type,
   126→      e.date as exercise_date
   127→    FROM signal_reports sr
   128→    JOIN operators o ON o.id = sr.operator_id
   129→    JOIN repeaters r ON r.id = sr.repeater_id
   130→    JOIN exercises e ON e.id = sr.exercise_id
   131→    WHERE sr.exercise_id IN (${placeholders})
   132→      AND sr.is_op_marker = 0
   133→      AND sr.readability IS NOT NULL
   134→    ORDER BY e.date, sr.created_at`
   135→  ).all(...ids) as any[];
   136→
   137→  // Build ADIF
   138→  const adifField = (name: string, value: string) => {
   139→    if (!value) return '';
   140→    return `<${name}:${value.length}>${value} `;
   141→  };
   142→
   143→  let adif = '';
   144→
   145→  // Header
   146→  adif += 'ADIF Export from BOS-ARSA Log\n';
   147→  adif += `https://bosarsalog.oeradio.at/\n`;
   148→  adif += `Date range: ${from} to ${to}\n`;
   149→  adif += `QSO count: ${reports.length}\n`;
   150→  adif += '\n';
   151→  adif += adifField('ADIF_VER', '3.1.4');
   152→  adif += adifField('PROGRAMID', 'BOS-ARSA Log');
   153→  adif += adifField('PROGRAMVERSION', '1.0.0-beta.5');
   154→  adif += '\n<EOH>\n\n';
   155→
   156→  // Records
   157→  for (const r of reports) {
   158→    const qsoDate = r.exercise_date.replace(/-/g, '');
   159→
   160→    // Extract time from created_at (format: "2026-02-16 14:30:00")
   161→    let timeOn = '0900'; // default
   162→    if (r.created_at) {
   163→      const timePart = r.created_at.split(' ')[1];
   164→      if (timePart) {
   165→        timeOn = timePart.replace(/:/g, '').slice(0, 4);
   166→      }
   167→    }
   168→
   169→    // RST: combine readability + strength + optional dB
   170→    const rst = `${r.readability}${r.strength}`;
   171→
   172→    // Frequency in MHz as string
   173→    const freq = r.frequency_mhz ? String(r.frequency_mhz) : '';
   174→
   175→    // Band mapping
   176→    let band = r.band || '';
   177→    if (!band && r.frequency_mhz) {
   178→      if (r.frequency_mhz >= 144 && r.frequency_mhz < 148) band = '2m';
   179→      else if (r.frequency_mhz >= 430 && r.frequency_mhz < 440) band = '70cm';
   180→      else if (r.frequency_mhz >= 1240 && r.frequency_mhz < 1300) band = '23cm';
   181→    }
   182→
   183→    adif += adifField('CALL', r.callsign);
   184→    adif += adifField('QSO_DATE', qsoDate);
   185→    adif += adifField('TIME_ON', timeOn);
   186→    adif += adifField('MODE', 'FM');
   187→    if (band) adif += adifField('BAND', band);
   188→    if (freq) adif += adifField('FREQ', freq);
   189→    adif += adifField('RST_SENT', rst);
   190→    adif += adifField('RST_RCVD', rst);
   191→    if (r.op_name) adif += adifField('NAME', r.op_name);
   192→    if (r.qth) adif += adifField('QTH', r.qth);
   193→    if (r.notes) adif += adifField('COMMENT', r.notes);
   194→    adif += '<EOR>\n';
   195→  }
   196→
   197→  const filename = `BOS-ARSA_QSOs_${from}_${to}.adi`;
   198→  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
   199→  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
   200→  res.send(adif);
   201→});
