   377→interface BezirkRowProps {
   378→  bezirk: any;
   379→  reports: any[];
   380→  linkedRepeaters: any[];
   381→  defaultRepeaterId: number;
   382→  onSubmit: (repeaterId: number, form: EntryForm) => void;
   383→  onEdit: (report: any) => void;
   384→  onDelete: (id: number) => void;
   385→  editingId: number | null;
   386→  editForm: EntryForm;
   387→  onEditChange: (form: EntryForm) => void;
   388→  onEditSave: () => void;
   389→  onEditCancel: () => void;
   390→}
   391→
   392→function BezirkRow({ bezirk, reports, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, editingId, editForm, onEditChange, onEditSave, onEditCancel }: BezirkRowProps) {
   393→  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '' });
   394→  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
   395→  const callsignRef = useRef<CallsignInputRef>(null);
   396→
   397→  useEffect(() => {
   398→    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
   399→  }, [defaultRepeaterId]);
   400→
   401→  const handleSubmit = (e: FormEvent) => {
   402→    e.preventDefault();
   403→    if (!form.callsign && !form.operator) return;
   404→    if (!repeaterId) return;
   405→    onSubmit(repeaterId, form);
   406→    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '' });
   407→    setTimeout(() => callsignRef.current?.focus(), 50);
   408→  };
   409→
   410→  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
   411→    if (!form.operator?.id) return;
   412→    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
   413→    if (value === original) return;
   414→    apiFetch(`/api/v1/operators/${form.operator.id}`, {
   415→      method: 'PATCH',
   416→      body: JSON.stringify({ [field]: value || null }),
   417→    }).then(() => {
   418→      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
   419→    }).catch(() => {});
   420→  };
   421→
   422→  return (
   423→    <div className="px-2 sm:px-3 py-1.5">
   424→      {bezirk.code !== '??' && (
   425→        <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
   426→          <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
   427→            {bezirk.code}
   428→          </span>
   429→          <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
   430→          {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
   431→        </div>
   432→      )}
   433→
   434→      {reports.length > 0 && (
   435→        <table className="w-full text-xs mb-1">
   436→          <tbody>
   437→            {reports.map((r, idx) => (
   438→              <tr key={r.id} className="hover:bg-blue-50 group">
   439→                {editingId === r.id ? (
   440→                  <td colSpan={5} className="py-0.5">
   441→                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
   442→                      <span className="font-mono font-medium">{r.callsign}</span>
   443→                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
   444→                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
   445→                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
   446→                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
   447→                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
   448→                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
   449→                    </div>
   450→                  </td>
   451→                ) : (
   452→                  <>
   453→                    <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   454→                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
   455→                      <span className="font-mono font-medium">{r.callsign}</span>
   456→                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
   457→                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
   458→                    </td>
   459→                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
   460→                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   461→                    </td>
   462→                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
   463→                    <td className="py-0.5 w-4">
   464→                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   465→                    </td>
   466→                  </>
   467→                )}
   468→              </tr>
   469→            ))}
   470→          </tbody>
   471→        </table>
   472→      )}
   473→
   474→      <form onSubmit={handleSubmit} className="flex items-center gap-1">
   475→        {linkedRepeaters.length > 0 && (
   476→          <select
   477→            value={repeaterId || ''}
   478→            onChange={e => setRepeaterId(parseInt(e.target.value))}
   479→            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
   480→          >
   481→            {linkedRepeaters.map(r => (
   482→              <option key={r.id} value={r.id}>
   483→                {r.site_name || r.short_name}
   484→              </option>
   485→            ))}
   486→          </select>
   487→        )}
   488→        <CallsignInput
   489→          ref={callsignRef}
   490→          value={form.callsign}
   491→          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
   492→          onSelect={op => setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }))}
   493→          className="w-24 sm:w-28"
   494→        />
   495→        <input
   496→          type="text"
   497→          value={form.opName}
   498→          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
   499→          onBlur={e => saveOperatorField('name', e.target.value)}
   500→          placeholder="Name"
   501→          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
   502→        />
   503→        <input
   504→          type="text"
   505→          value={form.opQth}
   506→          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
   507→          onBlur={e => saveOperatorField('qth', e.target.value)}
   508→          placeholder="QTH"
   509→          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
   510→        />
   511→        <input
   512→          type="text"
   513→          value={form.rapport}
   514→          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
   515→          placeholder="5/9"
   516→          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   517→          onKeyDown={e => {
   518→            if (e.altKey && e.key >= '1' && e.key <= '9') {
   519→              e.preventDefault();
   520→              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
   521→            }
   522→          }}
   523→        />
   524→        <input
   525→          type="text"
   526→          value={form.notes}
   527→          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
   528→          placeholder="Sonst."
   529→          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[40px] sm:min-w-[60px] focus:outline-none focus:ring-1 focus:ring-blue-500"
   530→        />
   531→        <button type="submit" title="Rapport speichern (Enter)" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 py-0.5 rounded text-xs flex-shrink-0">
   532→          + ↵
   533→        </button>
   534→      </form>
   535→    </div>
   536→  );
   537→}
